:host {
    --_accent: var(--integration-restaurant-accent, #39ad65);
    --_background: var(--integration-restaurant-content-background, #f5f1e9);
    --_border: var(--integration-restaurant-content-border, #ddd8cf);
    --_muted: var(--integration-restaurant-content-muted-text, #60665f);
    --_surface: var(--integration-restaurant-content-surface, #fffaf2);
    --_text: var(--integration-restaurant-content-text, #202421);
    --integration-basic-blocs-focus-color: var(--_accent);
    --integration-basic-blocs-surface-background: transparent;
    --integration-basic-blocs-surface-border: var(--_border);
    --integration-basic-blocs-surface-radius: 0.75rem;
    --integration-basic-blocs-surface-text: var(--_text);
    --integration-basic-blocs-table-font-size: 1rem;
    display: block;
    min-width: 0;
    color: var(--_text);
    background: var(--_background);
    font-family: var(--integration-restaurant-font-body, Inter, system-ui, sans-serif);
}

*,
*::before,
*::after {
    box-sizing: border-box;
}

:host([scheme="dark"]) {
    --integration-restaurant-content-background: var(--integration-restaurant-background, #15171a);
    --integration-restaurant-content-surface: var(--integration-restaurant-surface, #1d2124);
    --integration-restaurant-content-text: var(--integration-restaurant-text, #fffaf0);
    --integration-restaurant-content-muted-text: var(--integration-restaurant-muted-text, #d0cbc1);
    --integration-restaurant-content-border: color-mix(in srgb, var(--integration-restaurant-text, #fffaf0) 18%, transparent);
}

[part="section"] {
    min-width: 0;
    padding: clamp(3rem, 6vw, 6rem) clamp(1rem, 4vw, 3rem);
}

[part="card"] {
    width: min(100%, 76rem);
    min-width: 0;
    margin-inline: auto;
}

:host([surface="card"]) [part="card"] {
    padding: clamp(1.5rem, 4vw, 3rem);
    border: 1px solid var(--_border);
    border-radius: clamp(1rem, 2vw, 1.5rem);
    background: var(--_surface);
    box-shadow: 0 1.5rem 4rem color-mix(in srgb, var(--_text) 8%, transparent);
}

[part="header"] {
    display: flex;
    min-width: 0;
    align-items: flex-start;
    justify-content: space-between;
    gap: 1.5rem;
    margin-block-end: 2.25rem;
}

[part="heading"] {
    min-width: 0;
}

[part="title"] {
    min-width: 0;
}

[part="description"] {
    max-width: 42rem;
    margin-block-start: 0.75rem;
    color: var(--_muted);
    font-size: 1rem;
    line-height: 1.6;
}

[part="status"] {
    flex: none;
}

[part="content"] {
    display: grid;
    grid-template-columns: minmax(16rem, 0.85fr) 1px minmax(24rem, 1.35fr);
    min-width: 0;
    align-items: stretch;
    gap: clamp(1.5rem, 4vw, 3rem);
}

[part="contacts"] {
    display: grid;
    min-width: 0;
    align-content: start;
    gap: 1.75rem;
    margin: 0;
    font-style: normal;
}

[part="divider"] {
    width: 1px;
    min-height: 100%;
    background: var(--_border);
}

[part="hours-panel"],
[part="hours"] {
    min-width: 0;
}

[part="hours-title"] {
    margin-block-end: 1rem;
}

[part="note"] {
    margin-block-start: 1.5rem;
    color: var(--_muted);
    font-size: 1rem;
    line-height: 1.5;
}

::slotted([slot="title"]),
::slotted([slot="description"]),
::slotted([slot="hours-title"]),
::slotted([slot="note"]) {
    margin: 0;
}

::slotted([slot="title"]),
::slotted([slot="hours-title"]) {
    font-family: var(--integration-restaurant-font-heading, Georgia, "Times New Roman", serif);
    overflow-wrap: anywhere;
}

:host([presentation="stacked"]) [part="content"] {
    grid-template-columns: minmax(0, 1fr);
}

:host([presentation="stacked"]) [part="contacts"] {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}

:host([presentation="stacked"]) [part="divider"] {
    width: 100%;
    min-height: 1px;
}

:host([presentation="sidebar"]) [part="contacts"] {
    gap: 1.25rem;
}

:host([presentation="sidebar"]) [part="divider"] {
    display: block;
}

:host([presentation="sidebar"]) [part="content"] {
    grid-template-columns: minmax(15rem, 0.7fr) 1px minmax(22rem, 1.3fr);
    gap: clamp(1.5rem, 3vw, 2.5rem);
}

:host([presentation="sidebar"]) [part="card"] {
    width: min(100%, 68rem);
}

:host([presentation="sidebar"]) [part="header"] {
    margin-block-end: 1.75rem;
}

:host([density="compact"]) [part="section"] {
    padding-block: 2.5rem;
}

:host([density="compact"]) [part="header"] {
    margin-block-end: 1.5rem;
}

:host([density="compact"]) [part="contacts"] {
    gap: 1.25rem;
}

:host([density="spacious"]) [part="section"] {
    padding-block: clamp(5rem, 8vw, 8rem);
}

:host([density="spacious"]) [part="header"] {
    margin-block-end: 3rem;
}

@media (max-width: 820px) {
    [part="content"],
    :host([presentation="sidebar"]) [part="content"] {
        grid-template-columns: minmax(0, 1fr);
    }

    [part="divider"] {
        width: 100%;
        min-height: 1px;
    }

    :host([presentation="sidebar"]) [part="divider"] {
        display: block;
    }
}

@media (max-width: 560px) {
    [part="section"] {
        padding-inline: 0.75rem;
    }

    :host([surface="card"]) [part="card"] {
        padding: 1.25rem;
        border-radius: 1rem;
    }

    [part="header"] {
        display: grid;
        gap: 1rem;
        margin-block-end: 1.75rem;
    }

    [part="status"] {
        grid-row: 1;
        justify-self: start;
    }

    [part="content"] {
        gap: 1.5rem;
    }

    :host([presentation="stacked"]) [part="contacts"] {
        grid-template-columns: minmax(0, 1fr);
    }

}

@media (max-width: 360px) {
    :host([surface="card"]) [part="card"] {
        padding-inline: 1rem;
    }
}

