    overflow-x: auto;
    border-block-end: 1px solid var(--_border);
    scrollbar-width: thin;
    scroll-snap-type: inline proximity;
}

[part="categories"] button {
    position: relative;
    display: grid;
    flex: 1 0 8rem;
    min-width: 8rem;
    min-height: 5.5rem;
    padding: 0.75rem 1rem 1rem;
