    background: transparent;
    font: inherit;
    font-size: 1rem;
    font-weight: 650;
    cursor: pointer;
    scroll-snap-align: center;
}

[part="categories"] button::after {
    position: absolute;
    inset: auto 1rem 0;
    height: 0.2rem;
    border-radius: 999px;
    background: currentColor;
    content: "";
    opacity: 0;
    transform: scaleX(0.4);
    transition: opacity 180ms ease, transform 180ms ease;
}

[part="categories"] button:hover,
[part="categories"] button[aria-selected="true"] {
    color: var(--_text);
}

[part="categories"] button[aria-selected="true"]::after {
    color: var(--_accent);
    opacity: 1;
    transform: scaleX(1);
}

[part="categories"] button:focus-visible {
    outline: 3px solid color-mix(in srgb, var(--_accent) 70%, white);
    outline-offset: -3px;
    border-radius: 0.75rem;
}

[part="categories"] [data-icon] {
    display: grid;
    width: 1.75rem;
    height: 1.75rem;
    place-items: center;
    color: var(--_accent);
}

[part="categories"] svg {
    width: 100%;
    height: 100%;
    fill: none;
    stroke: currentColor;
}

[part="sections"] {
    min-width: 0;
}

::slotted([slot="title"]),
