export class RestaurantHeroCover extends Component {
    static observedAttributes = ["autoplay", "rotation-interval"];

    carousel = new RestaurantCarouselController(this);

    constructor() {
        super({ css: `${baseCss}\n${mediaCss}\n${responsiveCss}`, template });
    }

    connectedCallback() {
        this.carousel.connect();
