blocs/restaurant-menu/styles/base.css.content:
:host {
    --_accent: var(--integration-restaurant-accent, #39ad65);
    --_background: var(--integration-restaurant-background, #15171a);
    --_color: var(--integration-restaurant-text, #fffaf0);
    --_duration: 620ms;
    --_muted: var(--integration-restaurant-muted-text, #d0cbc1);

    position: fixed;
    z-index: 100;
    inset: 0;
    display: block;
    visibility: hidden;
    color: var(--_color);
    font-family: var(--integration-restaurant-font-body, system-ui, sans-serif);
    pointer-events: none;
    transition: visibility 0s var(--_duration);
}

:host([hidden]) { display: none !important; }
:host([open]) { visibility: visible; pointer-events: auto; transition-delay: 0s; }
:host([motion="snappy"]) { --_duration: 320ms; }

[part="backdrop"] {
    position: absolute;
    inset: 0;
    background: #050708b8;
    opacity: 0;
    transition: opacity var(--_duration) ease;
}

:host([open]) [part="backdrop"] { opacity: 1; }

[part="panel"] {
    position: absolute;
    display: grid;
    grid-template-rows: auto minmax(0, 1fr) auto;
    box-sizing: border-box;
    overflow: hidden;
    background:
        radial-gradient(circle at 76% 16%, color-mix(in srgb, var(--_accent) 10%, transparent), transparent 26rem),
        var(--_background);
    color: inherit;
    outline: none;
    transition: transform var(--_duration) cubic-bezier(.76, 0, .24, 1), opacity var(--_duration) ease;
}

[part="header"],
[part="footer"] {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: clamp(1.25rem, 3vw, 2.5rem) clamp(1.25rem, 4vw, 4rem);
    gap: 1.5rem;
}

[part="brand"] { min-width: 0; }

[part="close"] {
    display: flex;
    align-items: center;
    padding: .5rem 0;
    border: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    font-size: 1rem;
    text-transform: uppercase;
    cursor: pointer;
    gap: .75rem;
}

[part="close-icon"] { position: relative; width: 1.5rem; height: 1.5rem; }
[part="close-icon"] i { position: absolute; top: 50%; width: 100%; height: 1px; background: currentColor; }
[part="close-icon"] i:first-child { transform: rotate(45deg); }
[part="close-icon"] i:last-child { transform: rotate(-45deg); }

[part="layout"] {
    display: grid;
    grid-template-columns: minmax(18rem, .9fr) minmax(20rem, 1.1fr);
    min-height: 0;
    padding: 0 clamp(1.25rem, 4vw, 4rem);
    gap: clamp(2rem, 6vw, 7rem);
}

[part="primary"] { display: grid; align-content: center; min-width: 0; padding-block: 2rem; }
[part="eyebrow"] { margin-block-end: clamp(1.5rem, 4vh, 3rem); color: var(--_muted); }
[part="navigation"] { display: grid; align-content: center; }
[part="secondary"] { display: flex; flex-wrap: wrap; margin-block-start: 2rem; gap: .75rem 1.5rem; }
[part="media"] { min-height: 0; overflow: hidden; }
[part="details"] { display: flex; flex-wrap: wrap; color: var(--_muted); gap: .5rem 1.5rem; }
[part="footer-links"] { display: flex; flex-wrap: wrap; gap: 1.5rem; }

::slotted([slot="brand"]) {
    color: inherit;
    font-family: var(--integration-restaurant-font-heading, Georgia, serif);
    font-size: clamp(1.25rem, 3vw, 2rem);
    letter-spacing: .18em;
    text-transform: uppercase;
}

::slotted([slot="eyebrow"]),
::slotted([slot="details"]) { font-size: 1rem; }

::slotted(a) { color: inherit; font-size: 1rem; text-underline-offset: .25em; }
::slotted(a[slot="navigation"]) {
    width: fit-content;
    font-family: var(--integration-restaurant-font-heading, Georgia, serif);
    font-size: clamp(2.5rem, 5vw, 5rem);
    line-height: 1.08;
    text-decoration: none;
}

::slotted(img[slot="media"]) { display: block; width: 100%; height: 100%; object-fit: cover; }

:host([layout="links"]) [part="layout"] { grid-template-columns: minmax(0, 1fr); }
:host([layout="links"]) [part="primary"] { justify-items: center; text-align: center; }
:host([layout="links"]) [part="navigation"] { justify-items: center; }
:host([layout="links"]) [part="media"],
:host([media="hide"]) [part="media"] { display: none; }

blocs/restaurant-menu/styles/presentatio.content:
:host([presentation="curtain"]) [part="panel"],
:host(:not([presentation])) [part="panel"] {
    inset: 0;
    transform: translateY(-100%);
}

:host([presentation="curtain"][open]) [part="panel"],
:host(:not([presentation])[open]) [part="panel"] { transform: translateY(0); }

:host([presentation="drawer"]) [part="panel"] {
    inset: 0 0 0 auto;
    width: min(92vw, 40rem);
    transform: translateX(100%);
}

:host([presentation="drawer"][open]) [part="panel"] { transform: translateX(0); }
:host([presentation="drawer"]) [part="layout"] { grid-template-columns: minmax(0, 1fr); }
:host([presentation="drawer"]) [part="primary"] { align-content: start; }
:host([presentation="drawer"]) [part="media"] { display: none; }
:host([presentation="drawer"]) ::slotted(a[slot="navigation"]) { font-size: clamp(2.25rem, 8vw, 4.5rem); }

:host([presentation="panel"]) [part="panel"] {
    inset: clamp(1rem, 5vw, 4rem);
    width: min(calc(100% - 2rem), 72rem);
    height: min(calc(100% - 2rem), 50rem);
    margin: auto;
    border: 1px solid color-mix(in srgb, var(--_color) 20%, transparent);
    opacity: 0;
    transform: translateY(1rem) scale(.97);
}

:host([presentation="panel"][open]) [part="panel"] { opacity: 1; transform: translateY(0) scale(1); }

blocs/restaurant-menu/styles/responsive..content:
@media (max-width: 640px) {
    [part="header"],
    [part="footer"] { padding: 1rem 1.25rem; }

    [part="header"] { min-height: var(--integration-restaurant-header-height, 4.25rem); }
    [part="layout"] {
        grid-template-columns: minmax(0, 1fr);
        padding: 0 1.25rem;
        gap: 0;
    }

    [part="primary"] { align-content: center; padding-block: 1rem; }
    [part="eyebrow"] { margin-block-end: 1.25rem; }
    [part="navigation"] { gap: .4rem; }
    [part="secondary"] { margin-block-start: 1.5rem; gap: .75rem 1rem; }
    [part="media"] { display: none; }
    [part="footer"] { align-items: flex-end; }
    [part="details"] { display: grid; gap: .25rem; }

    ::slotted([slot="brand"]) { font-size: 1.125rem; letter-spacing: .12em; }
    ::slotted(a[slot="navigation"]) { font-size: clamp(2.25rem, 12vw, 3.75rem); }

    :host([presentation="panel"]) [part="panel"] {
        inset: .5rem;
        width: calc(100% - 1rem);
        height: calc(100% - 1rem);
    }
}

@media (prefers-reduced-motion: reduce) {
    :host { --_duration: 1ms; }
}

@media (prefers-reduced-motion: no-preference) {
    ::slotted(a[slot="navigation"]) { transition: color 180ms ease, transform 180ms ease; }
    ::slotted(a[slot="navigation"]:hover) { color: var(--_accent); transform: translateX(.35rem); }
}

